From 211e6df588660d80c52d8a8242ee2c3a2fc6f215 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 11:15:02 +0100
Subject: [PATCH] libs/handler: use WPA-PSK for WPA2/WPA3 transition networks

Connecting to an access point that offers both WPA2-PSK and WPA3-SAE
always created a connection with SAE key management, which can never
connect on Wi-Fi cards without SAE support. Use WPA-PSK in that case.

BUG: 498858
---
 libs/handler.cpp | 2 +-
 1 file changed, 1 insertion(+), 1 deletion(-)

diff --git a/libs/handler.cpp b/libs/handler.cpp
index 1a8d79746..87fb39142 100644
--- a/libs/handler.cpp
+++ b/libs/handler.cpp
@@ -363,7 +363,7 @@ QCoro::Task<> Handler::addAndActivateConnectionInternal(const QString &device, c
         } else {
             if (ap->mode() == NetworkManager::AccessPoint::Adhoc) {
                 wifiSecurity->setKeyMgmt(NetworkManager::WirelessSecuritySetting::WpaNone);
-            } else if (securityType == NetworkManager::SAE) {
+            } else if (securityType == NetworkManager::SAE && !ap->rsnFlags().testFlag(NetworkManager::AccessPoint::KeyMgmtPsk)) {
                 wifiSecurity->setKeyMgmt(NetworkManager::WirelessSecuritySetting::SAE);
             } else {
                 wifiSecurity->setKeyMgmt(NetworkManager::WirelessSecuritySetting::WpaPsk);
-- 
